-- CHAMBA 024 — Chat: RPC SECURITY DEFINER (login teléfono / piloto sin auth.uid())SET statement_timeout = '60s';-- Participante explícito (no depende de auth.uid())CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS job_chat_user_can_access CASCADE;CREATE OR REPLACE FUNCTION job_chat_user_can_access(  p_servicio_id UUID,  p_user_id UUID)RETURNS BOOLEANLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT EXISTS (    SELECT 1    FROM jobs j    WHERE j.id = p_servicio_id      AND j.status <> 'cancelled'      AND (        j.created_by = p_user_id        OR j.assigned_worker_id = p_user_id        OR EXISTS (          SELECT 1          FROM job_assignments ja          WHERE ja.job_id = j.id            AND ja.worker_id = p_user_id            AND ja.selection_status = 'approved'        )      )  );$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS job_chat_user_can_write CASCADE;CREATE OR REPLACE FUNCTION job_chat_user_can_write(  p_servicio_id UUID,  p_user_id UUID)RETURNS BOOLEANLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT EXISTS (    SELECT 1    FROM jobs j    WHERE j.id = p_servicio_id      AND j.status IN ('taken', 'in_progress')      AND (        j.created_by = p_user_id        OR j.assigned_worker_id = p_user_id        OR EXISTS (          SELECT 1          FROM job_assignments ja          WHERE ja.job_id = j.id            AND ja.worker_id = p_user_id            AND ja.selection_status = 'approved'        )      )  );$$;-- Enviar mensaje (cliente o técnico)CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS send_job_chat_message CASCADE;CREATE OR REPLACE FUNCTION send_job_chat_message(  p_servicio_id UUID,  p_remitente_id UUID,  p_texto TEXT)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_msg   mensajes%ROWTYPE;  v_text  TEXT;BEGIN  v_text := trim(p_texto);  IF char_length(v_text) = 0 OR char_length(v_text) > 2000 THEN    RETURN jsonb_build_object('success', false, 'error', 'El mensaje debe tener entre 1 y 2000 caracteres');  END IF;  IF NOT job_chat_user_can_write(p_servicio_id, p_remitente_id) THEN    RETURN jsonb_build_object(      'success', false,      'error', 'No podés enviar mensajes en este servicio (debe estar en curso y vos ser parte del mismo)'    );  END IF;  INSERT INTO mensajes (servicio_id, remitente_id, texto)  VALUES (p_servicio_id, p_remitente_id, v_text)  RETURNING * INTO v_msg;  RETURN jsonb_build_object(    'success', true,    'message', jsonb_build_object(      'id', v_msg.id,      'servicio_id', v_msg.servicio_id,      'remitente_id', v_msg.remitente_id,      'texto', v_msg.texto,      'creado_al', v_msg.creado_al    )  );END;$$;-- Listar mensajesCREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_job_chat_messages CASCADE;CREATE OR REPLACE FUNCTION get_job_chat_messages(  p_servicio_id UUID,  p_caller_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_messages JSONB;BEGIN  IF NOT job_chat_user_can_access(p_servicio_id, p_caller_id) THEN    RETURN jsonb_build_object('success', false, 'error', 'No tenés acceso a esta conversación');  END IF;  SELECT COALESCE(    jsonb_agg(      jsonb_build_object(        'id', m.id,        'servicio_id', m.servicio_id,        'remitente_id', m.remitente_id,        'texto', m.texto,        'creado_al', m.creado_al      )      ORDER BY m.creado_al ASC    ),    '[]'::jsonb  )  INTO v_messages  FROM mensajes m  WHERE m.servicio_id = p_servicio_id;  RETURN jsonb_build_object('success', true, 'messages', v_messages);END;$$;GRANT EXECUTE ON FUNCTION job_chat_user_can_access(UUID, UUID) TO anon, authenticated;GRANT EXECUTE ON FUNCTION job_chat_user_can_write(UUID, UUID) TO anon, authenticated;GRANT EXECUTE ON FUNCTION send_job_chat_message(UUID, UUID, TEXT) TO anon, authenticated;GRANT EXECUTE ON FUNCTION get_job_chat_messages(UUID, UUID) TO anon, authenticated;